{
  "name": "Linux CTF Academy",
  "description": "An interactive, AI-powered Capture The Flag (CTF) environment to learn Linux command line, networking, and system administration skills."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Difficulty {
  EASY = 'Easy',
  MEDIUM = 'Medium',
  HARD = 'Hard'
}

export interface Level {
  id: number;
  title: string;
  description: string;
  difficulty: Difficulty;
  objective: string;
  flag: string; // The expected answer
  systemContext: string; // The AI prompt context defining the file system/environment for this level
  hints: string[];
}

export interface TerminalLine {
  id: string;
  type: 'input' | 'output' | 'error' | 'system';
  content: string;
  directory?: string;
}

export interface GameState {
  currentLevelId: number;
  completedLevelIds: number[];
  flagsFound: Record<number, boolean>;
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Level } from "../types";

// NOTE: In a real production app, you might proxy this through a backend to protect the key.
// For this frontend-only demo, we use the env variable directly.
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY is not defined in environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

export class TerminalService {
  private chatSession: Chat | null = null;
  private currentLevelId: number | null = null;

  async initializeSession(level: Level): Promise<void> {
    const ai = getClient();
    this.currentLevelId = level.id;

    // We create a new chat session for each level reset to clear context
    this.chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `
          ${level.systemContext}

          CRITICAL INSTRUCTIONS:
          1. Act ONLY as a Linux Terminal. Do not output markdown code blocks. Just raw text.
          2. Maintain the state of the Current Working Directory (CWD) across prompts if the user 'cd's.
          3. If the user runs a command that changes state (like 'touch' or 'mkdir'), simulate that success message, and remember it for the next 'ls'.
          4. If the user gets the flag, output it clearly in the terminal output.
          5. Handle standard commands: ls, cd, cat, grep, pwd, whoami, echo, env, printenv, curl, ping, netstat.
          6. If a command is unknown, output "command not found".
          7. Be concise.
        `,
        temperature: 0.1, // Low temperature for deterministic behavior
      },
    });
  }

  async sendCommand(command: string): Promise<string> {
    if (!this.chatSession) {
      return "Error: Terminal session not initialized. Please select a level.";
    }

    try {
      const response: GenerateContentResponse = await this.chatSession.sendMessage({
        message: command
      });

      // Basic cleanup to remove potential markdown code fences if the model slips up
      let text = response.text || "";
      text = text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
      return text.trim();
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "Error: Connection to simulation server interrupted.";
    }
  }

  async getHint(level: Level, currentHistory: string): Promise<string> {
    const ai = getClient();
    // Use a separate model call for hints so we don't pollute the terminal context with "Hint request"
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `
          The user is playing a CTF level.
          Level Objective: ${level.objective}
          Level Context: ${level.systemContext}

          The user is stuck. Their recent terminal history is:
          ${currentHistory.slice(-500)}

          Provide a helpful, cryptic hint. Do not give the direct answer or the flag.
          Be brief (max 1 sentence).
        `,
      });
      return response.text || "Try checking the manual pages (man) or listing files.";
    } catch (error) {
      return "Hints are currently unavailable.";
    }
  }
}

export const terminalService = new TerminalService();

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { TerminalLine } from '../types';
import { Play, RotateCcw } from 'lucide-react';

interface TerminalProps {
  lines: TerminalLine[];
  onCommand: (cmd: string) => void;
  isProcessing: boolean;
  onReset: () => void;
  cwd: string;
}

export const Terminal: React.FC<TerminalProps> = ({ 
  lines, 
  onCommand, 
  isProcessing, 
  onReset,
  cwd 
}) => {
  const [input, setInput] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [lines]);

  // Focus input on click anywhere in terminal
  const handleContainerClick = () => {
    // Don't focus if selecting text
    const selection = window.getSelection();
    if (selection && selection.type === 'Range') return;
    inputRef.current?.focus();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isProcessing) return;
    onCommand(input);
    setInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'c' && e.ctrlKey) {
       // Simulate Ctrl+C
       setInput('');
       onCommand('^C');
    }
  };

  return (
    <div 
      className="flex flex-col h-full bg-[#0f172a] rounded-lg border border-slate-700 overflow-hidden shadow-2xl font-mono text-sm md:text-base relative group"
      onClick={handleContainerClick}
    >
      {/* Terminal Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-slate-800 border-b border-slate-700 select-none">
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-green-500/80"></div>
          <span className="ml-2 text-slate-400 text-xs">cadet@linux-ctf:~</span>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); onReset(); }}
          className="p-1.5 hover:bg-slate-700 rounded-md text-slate-400 hover:text-white transition-colors flex items-center gap-1 text-xs"
          title="Reset Session"
        >
          <RotateCcw size={14} />
          Reset
        </button>
      </div>

      {/* Terminal Body */}
      <div className="flex-1 p-4 overflow-y-auto terminal-scroll space-y-1">
        {lines.map((line) => (
          <div key={line.id} className="break-words">
            {line.type === 'input' && (
              <div className="flex text-emerald-400 font-bold">
                <span className="mr-2 shrink-0">
                  <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{line.directory || '~'}</span>$
                </span>
                <span className="text-slate-100">{line.content}</span>
              </div>
            )}
            {line.type === 'output' && (
              <div className="text-slate-300 whitespace-pre-wrap ml-0">{line.content}</div>
            )}
            {line.type === 'error' && (
              <div className="text-red-400 whitespace-pre-wrap">{line.content}</div>
            )}
            {line.type === 'system' && (
              <div className="text-cyan-400 italic opacity-80 py-1">{line.content}</div>
            )}
          </div>
        ))}

        {/* Input Line */}
        <form onSubmit={handleSubmit} className="flex items-center text-slate-100">
           <span className="mr-2 text-emerald-400 font-bold shrink-0">
             <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{cwd}</span>$
           </span>
           <div className="relative flex-1">
            <input
              ref={inputRef}
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              className="w-full bg-transparent border-none outline-none text-slate-100 placeholder-slate-600 caret-emerald-400"
              autoComplete="off"
              autoFocus
              disabled={isProcessing}
            />
            {!isProcessing && (
              <div 
                className="absolute top-0 w-2.5 h-5 bg-emerald-400/50 animate-pulse pointer-events-none"
                style={{ left: `${input.length}ch` }} // Approximate cursor position
              />
            )}
           </div>
        </form>
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Level, Difficulty } from '../types';
import { Lock, Unlock, CheckCircle, Flag, HelpCircle, TerminalSquare } from 'lucide-react';

interface SidebarProps {
  levels: Level[];
  currentLevelId: number;
  completedLevelIds: number[];
  onSelectLevel: (id: number) => void;
  onSubmitFlag: (flag: string) => void;
  onRequestHint: () => void;
  hintLoading: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  levels,
  currentLevelId,
  completedLevelIds,
  onSelectLevel,
  onSubmitFlag,
  onRequestHint,
  hintLoading
}) => {
  const [flagInput, setFlagInput] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const currentLevel = levels.find(l => l.id === currentLevelId);

  const handleFlagSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentLevel) return;

    if (flagInput.trim() === currentLevel.flag) {
      setSuccessMsg('Correct! Level Complete.');
      setErrorMsg('');
      onSubmitFlag(flagInput);
      setFlagInput('');
      setTimeout(() => setSuccessMsg(''), 3000);
    } else {
      setErrorMsg('Incorrect Flag.');
      setSuccessMsg('');
      setTimeout(() => setErrorMsg(''), 3000);
    }
  };

  return (
    <div className="w-full md:w-80 bg-slate-900 border-r border-slate-800 flex flex-col h-full overflow-hidden">
      {/* Brand */}
      <div className="p-6 border-b border-slate-800 flex items-center space-x-3 bg-slate-950">
        <div className="p-2 bg-indigo-500/10 rounded-lg">
           <TerminalSquare className="text-indigo-400" size={24} />
        </div>
        <div>
          <h1 className="font-bold text-lg tracking-tight text-white">Linux CTF</h1>
          <p className="text-xs text-slate-500">System Mastery Course</p>
        </div>
      </div>

      {/* Levels List */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        <h2 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Modules</h2>
        {levels.map((level) => {
          const isCompleted = completedLevelIds.includes(level.id);
          const isActive = currentLevelId === level.id;
          const isLocked = level.id > 1 && !completedLevelIds.includes(level.id - 1) && !isActive;

          return (
            <button
              key={level.id}
              onClick={() => !isLocked && onSelectLevel(level.id)}
              disabled={isLocked}
              className={`w-full text-left p-3 rounded-lg border transition-all duration-200 group relative ${
                isActive 
                  ? 'bg-indigo-600/10 border-indigo-500/50 shadow-md shadow-indigo-900/20' 
                  : isLocked 
                    ? 'bg-slate-900/50 border-transparent opacity-60 cursor-not-allowed' 
                    : 'bg-slate-800/50 border-slate-700/50 hover:bg-slate-800 hover:border-slate-600'
              }`}
            >
              <div className="flex justify-between items-start mb-1">
                <span className={`text-sm font-medium ${isActive ? 'text-indigo-300' : 'text-slate-300'}`}>
                   {level.title}
                </span>
                {isCompleted ? (
                   <CheckCircle size={16} className="text-emerald-500" />
                ) : isLocked ? (
                   <Lock size={16} className="text-slate-600" />
                ) : (
                   <Unlock size={16} className="text-slate-500 group-hover:text-slate-400" />
                )}
              </div>
              <div className="flex items-center gap-2">
                 <span className={`text-[10px] px-1.5 py-0.5 rounded ${
                   level.difficulty === Difficulty.EASY ? 'bg-green-500/10 text-green-400' :
                   level.difficulty === Difficulty.MEDIUM ? 'bg-yellow-500/10 text-yellow-400' :
                   'bg-red-500/10 text-red-400'
                 }`}>
                   {level.difficulty}
                 </span>
              </div>
            </button>
          );
        })}
      </div>

      {/* Current Mission & Flag Submission */}
      <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-sm z-10">
        {currentLevel && (
          <div className="space-y-4">
            <div>
              <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">Current Objective</h3>
              <p className="text-sm text-slate-300 leading-relaxed bg-slate-800/50 p-3 rounded-md border border-slate-700/50">
                {currentLevel.objective}
              </p>
            </div>

            <div className="flex gap-2">
               <button
                 onClick={onRequestHint}
                 disabled={hintLoading}
                 className="text-xs flex items-center gap-1.5 text-indigo-400 hover:text-indigo-300 transition-colors px-2 py-1 hover:bg-indigo-500/10 rounded-md disabled:opacity-50"
               >
                 <HelpCircle size={14} />
                 {hintLoading ? 'Thinking...' : 'Need a hint?'}
               </button>
            </div>

            <form onSubmit={handleFlagSubmit} className="space-y-2">
              <label className="block text-xs font-medium text-slate-400">Capture The Flag</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Flag className="absolute left-3 top-2.5 text-slate-500" size={14} />
                  <input 
                    type="text" 
                    value={flagInput}
                    onChange={(e) => setFlagInput(e.target.value)}
                    placeholder="CTF{...}" 
                    className="w-full bg-slate-950 border border-slate-700 text-slate-200 text-sm rounded-md py-2 pl-9 pr-3 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-600"
                  />
                </div>
                <button 
                  type="submit"
                  className="bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium px-4 rounded-md transition-colors shadow-lg shadow-indigo-900/20"
                >
                  Submit
                </button>
              </div>
              {errorMsg && <p className="text-xs text-red-400 animate-pulse">{errorMsg}</p>}
              {successMsg && <p className="text-xs text-emerald-400 font-medium">{successMsg}</p>}
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { Terminal } from './components/Terminal';
import { LEVELS, TERMINAL_WELCOME } from './constants';
import { TerminalLine, GameState } from './types';
import { terminalService } from './services/geminiService';
import { Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    currentLevelId: 1,
    completedLevelIds: [],
    flagsFound: {},
  });

  const [terminalLines, setTerminalLines] = useState<TerminalLine[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [hintLoading, setHintLoading] = useState(false);
  const [cwd, setCwd] = useState('~');

  // Load level on start or change
  useEffect(() => {
    loadLevel(gameState.currentLevelId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gameState.currentLevelId]);

  const addLine = (content: string, type: TerminalLine['type'], directory?: string) => {
    setTerminalLines(prev => [...prev, {
      id: Math.random().toString(36).substring(7),
      type,
      content,
      directory
    }]);
  };

  const loadLevel = async (levelId: number) => {
    setIsProcessing(true);
    const level = LEVELS.find(l => l.id === levelId);
    if (!level) return;

    setTerminalLines([]); // Clear terminal
    setCwd('~');

    // Initial welcome messages
    TERMINAL_WELCOME.forEach(line => addLine(line, 'system'));
    addLine(`Loaded Level ${level.id}: ${level.title}`, 'system');
    addLine(level.description, 'system');

    try {
      await terminalService.initializeSession(level);
      addLine(`Ready.`, 'system');
    } catch (e) {
      addLine(`Error initializing simulation: ${e}`, 'error');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCommand = async (command: string) => {
    if (!command) return;

    // Echo user command
    addLine(command, 'input', cwd);

    // Handle client-side commands
    if (command.trim() === 'clear') {
      setTerminalLines([]);
      return;
    }

    setIsProcessing(true);
    try {
      const output = await terminalService.sendCommand(command);

      // Attempt to parse CWD change from output if the AI was instructed to echo it (advanced)
      // For this simplified version, we rely on the prompt to generally behave, 
      // but let's do a simple heuristic if the user typed 'cd'
      if (command.startsWith('cd ') && !output.toLowerCase().includes('no such file')) {
         // This is a naive client-side update for visual flair. 
         // The real state is in the AI session context.
         const target = command.split(' ')[1];
         if (target === '..') {
            setCwd(prev => prev === '~' ? '/' : prev.split('/').slice(0, -1).join('/') || '/');
         } else if (target === '~') {
            setCwd('~');
         } else if (target.startsWith('/')) {
            setCwd(target);
         } else {
            setCwd(prev => prev === '~' || prev === '/' ? `${prev === '/' ? '' : prev}/${target}` : `${prev}/${target}`);
         }
      }

      addLine(output, 'output');
    } catch (error) {
      addLine("Communication error with shell.", 'error');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFlagSubmit = (flag: string) => {
    if (!gameState.completedLevelIds.includes(gameState.currentLevelId)) {
      setGameState(prev => ({
        ...prev,
        completedLevelIds: [...prev.completedLevelIds, prev.currentLevelId],
        flagsFound: { ...prev.flagsFound, [prev.currentLevelId]: true }
      }));
      addLine(`Success! Flag captured for Level ${gameState.currentLevelId}`, 'system');
      addLine(`Use the sidebar to select the next level.`, 'system');
    }
  };

  const handleRequestHint = async () => {
    setHintLoading(true);
    const level = LEVELS.find(l => l.id === gameState.currentLevelId);
    if (level) {
       // Serialize recent history for context
       const historyText = terminalLines
        .slice(-10)
        .map(l => `${l.type === 'input' ? '> ' : ''}${l.content}`)
        .join('\n');

       const hint = await terminalService.getHint(level, historyText);
       addLine(`HINT: ${hint}`, 'system');
    }
    setHintLoading(false);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 overflow-hidden">
      {/* Mobile Menu Toggle */}
      <button 
        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        className="md:hidden absolute top-4 right-4 z-50 p-2 bg-slate-800 text-slate-200 rounded-md border border-slate-700"
      >
        {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
      </button>

      {/* Sidebar - Hidden on mobile unless toggled */}
      <div className={`
        fixed inset-y-0 left-0 z-40 w-80 transform transition-transform duration-300 ease-in-out md:relative md:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <Sidebar 
          levels={LEVELS}
          currentLevelId={gameState.currentLevelId}
          completedLevelIds={gameState.completedLevelIds}
          onSelectLevel={(id) => {
            setGameState(prev => ({ ...prev, currentLevelId: id }));
            setIsMobileMenuOpen(false);
          }}
          onSubmitFlag={handleFlagSubmit}
          onRequestHint={handleRequestHint}
          hintLoading={hintLoading}
        />
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 h-full p-4 md:p-6 relative">
         {/* Background Grid Effect */}
         <div className="absolute inset-0 z-0 opacity-[0.03] pointer-events-none" 
              style={{ 
                backgroundImage: 'linear-gradient(to right, #ffffff 1px, transparent 1px), linear-gradient(to bottom, #ffffff 1px, transparent 1px)', 
                backgroundSize: '40px 40px' 
              }}
         ></div>

         <div className="z-10 flex-1 flex flex-col max-w-5xl mx-auto w-full">
            <div className="mb-4">
               <h2 className="text-xl md:text-2xl font-bold text-white tracking-tight">
                 {LEVELS.find(l => l.id === gameState.currentLevelId)?.title}
               </h2>
               <p className="text-slate-400 text-sm md:text-base mt-1">
                 {LEVELS.find(l => l.id === gameState.currentLevelId)?.description}
               </p>
            </div>

            <div className="flex-1 min-h-0 shadow-2xl rounded-lg overflow-hidden border border-slate-700/50">
               <Terminal 
                 lines={terminalLines}
                 onCommand={handleCommand}
                 isProcessing={isProcessing}
                 onReset={() => loadLevel(gameState.currentLevelId)}
                 cwd={cwd}
               />
            </div>
         </div>
      </div>

      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-30 md:hidden backdrop-blur-sm"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Level } from "../types";

// NOTE: In a real production app, you might proxy this through a backend to protect the key.
// For this frontend-only demo, we use the env variable directly.
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY is not defined in environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

export class TerminalService {
  private chatSession: Chat | null = null;
  private currentLevelId: number | null = null;

  async initializeSession(level: Level): Promise<void> {
    const ai = getClient();
    this.currentLevelId = level.id;

    // We create a new chat session for each level reset to clear context
    this.chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `
          You are a strict Linux Terminal Simulator (Bash).

          LEVEL CONTEXT:
          ${level.systemContext}

          RULES:
          1. Act ONLY as the terminal. Output raw text. NO Markdown blocks. NO conversational filler.
          2. Maintain state (CWD, variables, file permissions simulation).
          3. If the user finds the flag, output it plainly.
          4. Command handling:
             - 'ls': List files in CWD.
             - 'cd': Change CWD (update your internal state).
             - 'cat': Output file content.
             - 'pwd': Print CWD.
             - 'whoami': Print 'cadet'.
             - 'export': Set env vars (remember them).
             - 'sudo': Simulate root access (if allowed by context).
             - 'chmod': Simulate permission change.
             - Unknown command: "command not found".
          5. Be realistic. If a file doesn't exist, say "No such file or directory".
          6. Do not give hints unless explicitly asked (but this prompt is for the terminal loop, not hints).
          7. Output formatting: Mimic real linux output (e.g., ls -l format).
        `,
        temperature: 0.1, 
      },
    });
  }

  async sendCommand(command: string): Promise<string> {
    if (!this.chatSession) {
      return "Error: Terminal session not initialized. Please select a level.";
    }

    try {
      const response: GenerateContentResponse = await this.chatSession.sendMessage({
        message: command
      });

      // Basic cleanup to remove potential markdown code fences if the model slips up
      let text = response.text || "";
      text = text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
      return text.trim();
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "Error: Connection to simulation server interrupted.";
    }
  }

  async getHint(level: Level, currentHistory: string): Promise<string> {
    const ai = getClient();
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `
          User is playing CTF Level ${level.id}: ${level.title}.
          Objective: ${level.objective}
          Context: ${level.systemContext}

          User History:
          ${currentHistory.slice(-500)}

          Provide a short, specific hint (max 1 sentence) to help them proceed without giving the flag directly.
        `,
      });
