import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Terminal } from './components/Terminal';
import { LEVELS, TERMINAL_WELCOME } from './constants';
import { TerminalLine, GameState } from './types';
import { terminalService } from './services/geminiService';
import { Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    currentLevelId: 1,
    completedLevelIds: [],
    flagsFound: {},
  });

  const [terminalLines, setTerminalLines] = useState<TerminalLine[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [cwd, setCwd] = useState('~');

  // Load level on start or change
  useEffect(() => {
    loadLevel(gameState.currentLevelId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gameState.currentLevelId]);

  const addLine = (content: string, type: TerminalLine['type'], directory?: string) => {
    setTerminalLines(prev => [...prev, {
      id: Math.random().toString(36).substring(7),
      type,
      content,
      directory
    }]);
  };

  const loadLevel = async (levelId: number) => {
    setIsProcessing(true);
    const level = LEVELS.find(l => l.id === levelId);
    if (!level) return;

    setTerminalLines([]); // Clear terminal
    setCwd('~');

    // Initial welcome messages
    TERMINAL_WELCOME.forEach(line => addLine(line, 'system'));
    addLine(`Loaded Level ${level.id}: ${level.title}`, 'system');
    addLine(level.description, 'system');

    try {
      await terminalService.initializeSession(level);
      addLine(`Ready.`, 'system');
    } catch (e) {
      addLine(`Error initializing simulation: ${e}`, 'error');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCommand = async (command: string) => {
    if (!command) return;

    // Echo user command
    addLine(command, 'input', cwd);

    // Handle client-side commands
    if (command.trim() === 'clear') {
      setTerminalLines([]);
      return;
    }

    setIsProcessing(true);
    try {
      const output = await terminalService.sendCommand(command);

      // Attempt to parse CWD change from output if the AI was instructed to echo it (advanced)
      // For this simplified version, we rely on the prompt to generally behave, 
      // but let's do a simple heuristic if the user typed 'cd'
      if (command.startsWith('cd ') && !output.toLowerCase().includes('no such file')) {
         // This is a naive client-side update for visual flair. 
         // The real state is in the AI session context.
         const target = command.split(' ')[1];
         if (target === '..') {
            setCwd(prev => prev === '~' ? '/' : prev.split('/').slice(0, -1).join('/') || '/');
         } else if (target === '~') {
            setCwd('~');
         } else if (target.startsWith('/')) {
            setCwd(target);
         } else {
            setCwd(prev => prev === '~' || prev === '/' ? `${prev === '/' ? '' : prev}/${target}` : `${prev}/${target}`);
         }
      }

      addLine(output, 'output');
    } catch (error) {
      addLine("Communication error with shell.", 'error');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 overflow-hidden">
      {/* Mobile Menu Toggle */}
      <button 
        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        className="md:hidden absolute top-4 right-4 z-50 p-2 bg-slate-800 text-slate-200 rounded-md border border-slate-700"
      >
        {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
      </button>

      {/* Sidebar - Hidden on mobile unless toggled */}
      <div className={`
        fixed inset-y-0 left-0 z-40 w-80 transform transition-transform duration-300 ease-in-out md:relative md:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <Sidebar 
          levels={LEVELS}
          currentLevelId={gameState.currentLevelId}
          onSelectLevel={(id) => {
            setGameState(prev => ({ ...prev, currentLevelId: id }));
            setIsMobileMenuOpen(false);
          }}
        />
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 h-full p-4 md:p-6 relative">
         {/* Background Grid Effect */}
         <div className="absolute inset-0 z-0 opacity-[0.03] pointer-events-none" 
              style={{ 
                backgroundImage: 'linear-gradient(to right, #ffffff 1px, transparent 1px), linear-gradient(to bottom, #ffffff 1px, transparent 1px)', 
                backgroundSize: '40px 40px' 
              }}
         ></div>

         <div className="z-10 flex-1 flex flex-col max-w-5xl mx-auto w-full">
            <div className="mb-4">
               <h2 className="text-xl md:text-2xl font-bold text-white tracking-tight">
                 {LEVELS.find(l => l.id === gameState.currentLevelId)?.title}
               </h2>
               <p className="text-slate-400 text-sm md:text-base mt-1">
                 {LEVELS.find(l => l.id === gameState.currentLevelId)?.description}
               </p>
            </div>

            <div className="flex-1 min-h-0 shadow-2xl rounded-lg overflow-hidden border border-slate-700/50">
               <Terminal 
                 lines={terminalLines}
                 onCommand={handleCommand}
                 isProcessing={isProcessing}
                 onReset={() => loadLevel(gameState.currentLevelId)}
                 cwd={cwd}
               />
            </div>
         </div>
      </div>

      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-30 md:hidden backdrop-blur-sm"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Level } from "../types";

// NOTE: In a real production app, you might proxy this through a backend to protect the key.
// For this frontend-only demo, we use the env variable directly.
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY is not defined in environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

export class TerminalService {
  private chatSession: Chat | null = null;
  private currentLevelId: number | null = null;

  async initializeSession(level: Level): Promise<void> {
    const ai = getClient();
    this.currentLevelId = level.id;

    // We create a new chat session for each level reset to clear context
    this.chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `
          You are a strict Linux Terminal Simulator (Bash).

          LEVEL CONTEXT:
          ${level.systemContext}

          RULES:
          1. Act ONLY as the terminal. Output raw text. NO Markdown blocks. NO conversational filler.
          2. Maintain state (CWD, variables, file permissions simulation).
          3. If the user finds the flag, output it plainly.
          4. Command handling:
             - 'ls': List files in CWD.
             - 'cd': Change CWD (update your internal state).
             - 'cat': Output file content.
             - 'pwd': Print CWD.
             - 'whoami': Print 'cadet'.
             - 'export': Set env vars (remember them).
             - 'sudo': Simulate root access (if allowed by context).
             - 'chmod': Simulate permission change.
             - Unknown command: "command not found".
          5. Be realistic. If a file doesn't exist, say "No such file or directory".
          6. Do not give hints unless explicitly asked (but this prompt is for the terminal loop, not hints).
          7. Output formatting: Mimic real linux output (e.g., ls -l format).
        `,
        temperature: 0.1, 
      },
    });
  }

  async sendCommand(command: string): Promise<string> {
    if (!this.chatSession) {
      return "Error: Terminal session not initialized. Please select a level.";
    }

    try {
      const response: GenerateContentResponse = await this.chatSession.sendMessage({
        message: command
      });

      // Basic cleanup to remove potential markdown code fences if the model slips up
      let text = response.text || "";
      text = text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
      return text.trim();
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "Error: Connection to simulation server interrupted.";
    }
  }
}

export const terminalService = new TerminalService();

import React, { useState, useEffect, useRef } from 'react';
import { TerminalLine } from '../types';
import { RotateCcw } from 'lucide-react';

interface TerminalProps {
  lines: TerminalLine[];
  onCommand: (cmd: string) => void;
  isProcessing: boolean;
  onReset: () => void;
  cwd: string;
}

export const Terminal: React.FC<TerminalProps> = ({ 
  lines, 
  onCommand, 
  isProcessing, 
  onReset,
  cwd 
}) => {
  const [input, setInput] = useState('');
  const [history, setHistory] = useState<string[]>([]);
  const [historyPointer, setHistoryPointer] = useState<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [lines]);

  // Focus input on click anywhere in terminal
  const handleContainerClick = () => {
    // Don't focus if selecting text
    const selection = window.getSelection();
    if (selection && selection.type === 'Range') return;
    inputRef.current?.focus();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isProcessing) return;

    setHistory(prev => [...prev, input]);
    setHistoryPointer(null);

    onCommand(input);
    setInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'c' && e.ctrlKey) {
       // Simulate Ctrl+C
       setInput('');
       setHistoryPointer(null);
       onCommand('^C');
       return;
    }

    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (history.length === 0) return;

      const newPointer = historyPointer === null 
        ? history.length - 1 
        : Math.max(0, historyPointer - 1);

      setHistoryPointer(newPointer);
      setInput(history[newPointer]);
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (historyPointer === null) return;

      const newPointer = historyPointer + 1;
      if (newPointer >= history.length) {
        setHistoryPointer(null);
        setInput('');
      } else {
        setHistoryPointer(newPointer);
        setInput(history[newPointer]);
      }
    }
  };

  return (
    <div 
      className="flex flex-col h-full bg-[#0f172a] rounded-lg border border-slate-700 overflow-hidden shadow-2xl font-mono text-sm md:text-base relative group"
      onClick={handleContainerClick}
    >
      {/* Terminal Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-slate-800 border-b border-slate-700 select-none">
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-green-500/80"></div>
          <span className="ml-2 text-slate-400 text-xs">cadet@linux-ctf:~</span>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); onReset(); }}
          className="p-1.5 hover:bg-slate-700 rounded-md text-slate-400 hover:text-white transition-colors flex items-center gap-1 text-xs"
          title="Reset Session"
        >
          <RotateCcw size={14} />
          Reset
        </button>
      </div>

      {/* Terminal Body */}
      <div className="flex-1 p-4 overflow-y-auto terminal-scroll space-y-1">
        {lines.map((line) => (
          <div key={line.id} className="break-words">
            {line.type === 'input' && (
              <div className="flex text-emerald-400 font-bold">
                <span className="mr-2 shrink-0">
                  <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{line.directory || '~'}</span>$
                </span>
                <span className="text-slate-100">{line.content}</span>
              </div>
            )}
            {line.type === 'output' && (
              <div className="text-slate-300 whitespace-pre-wrap ml-0">{line.content}</div>
            )}
            {line.type === 'error' && (
              <div className="text-red-400 whitespace-pre-wrap">{line.content}</div>
            )}
            {line.type === 'system' && (
              <div className="text-cyan-400 italic opacity-80 py-1">{line.content}</div>
            )}
          </div>
        ))}

        {/* Input Line */}
        <form onSubmit={handleSubmit} className="flex items-center text-slate-100">
           <span className="mr-2 text-emerald-400 font-bold shrink-0">
             <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{cwd}</span>$
           </span>
           <div className="relative flex-1">
            <input
              ref={inputRef}
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              className="w-full bg-transparent border-none outline-none text-slate-100 placeholder-slate-600 caret-emerald-400"
              autoComplete="off"
              autoFocus
              disabled={isProcessing}
            />
            {!isProcessing && (
              <div 
                className="absolute top-0 w-2.5 h-5 bg-emerald-400/50 animate-pulse pointer-events-none"
                style={{ left: `${input.length}ch` }} // Approximate cursor position
              />
            )}
           </div>
        </form>
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

