  return new GoogleGenAI({ apiKey });
};

export class TerminalService {
  private chatSession: Chat | null = null;
  private currentLevelId: number | null = null;
  private isOffline: boolean = false;

  async initializeSession(level: Level): Promise<string> {
    this.currentLevelId = level.id;
    const ai = getClient();

    if (!ai) {
      this.isOffline = true;
      this.chatSession = null;
      return "⚠️ API_KEY not found. Starting in OFFLINE MODE. AI features disabled.";
    }

    this.isOffline = false;

    // We create a new chat session for each level reset to clear context
    this.chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `
          You are a strict Linux Terminal Simulator (Bash).

          LEVEL CONTEXT:
          ${level.systemContext}

          RULES:
          1. Act ONLY as the terminal. Output raw text. NO Markdown blocks. NO conversational filler.
          2. Maintain state (CWD, variables, file permissions simulation).
          3. If the user finds the flag, output it plainly.
          4. Command handling:
             - 'ls': List files in CWD.
             - 'cd': Change CWD (update your internal state).
             - 'cat': Output file content.
             - 'pwd': Print CWD.
             - 'whoami': Print 'cadet'.
             - 'export': Set env vars (remember them).
             - 'sudo': Simulate root access (if allowed by context).
             - 'chmod': Simulate permission change.
             - Unknown command: "command not found".
          5. Be realistic. If a file doesn't exist, say "No such file or directory".
          6. Do not give hints unless explicitly asked (but this prompt is for the terminal loop, not hints).
          7. Output formatting: Mimic real linux output (e.g., ls -l format).
        `,
        temperature: 0.1, 
      },
    });

    return "Connected to AI Simulation Environment.";
  }

  async sendCommand(command: string): Promise<string> {
    if (this.isOffline) {
      return this.handleOfflineCommand(command);
    }

    if (!this.chatSession) {
      return "Error: Terminal session not initialized. Please reset the level.";
    }

    try {
      const response: GenerateContentResponse = await this.chatSession.sendMessage({
        message: command
      });

      // Basic cleanup to remove potential markdown code fences if the model slips up
      let text = response.text || "";
      text = text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
      return text.trim();
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "Error: Connection to simulation server interrupted.";
    }
  }

  private handleOfflineCommand(command: string): string {
    const parts = command.trim().split(/\s+/);
    const cmd = parts[0];
    const arg = parts[1] || "";

    switch (cmd) {
      case 'help':
        return "OFFLINE MODE ENABLED\n\nBecause no API_KEY was detected, the AI simulation is disabled.\nBasic commands available:\n  ls      - List dummy files\n  pwd     - Print working directory\n  whoami  - Print current user\n  echo    - Echo text\n  cd      - Change directory (simulation)\n  clear   - Clear screen\n\nTo play the actual CTF levels, please provide a valid Google GenAI API_KEY.";
      case 'ls':
        return "welcome.txt  instructions.md  offline_mode_active";
      case 'pwd':
        return "/home/cadet";
      case 'whoami':
        return "cadet";
      case 'echo':
        return parts.slice(1).join(' ');
      case 'cd':
        return ""; // Return empty to allow App.tsx to update prompt path visually
      case 'cat':
        return "Offline Mode: Cannot read specific file contents from level definition without AI.\n(This is a placeholder response)";
      default:
        return `bash: ${cmd}: command not found (Offline Mode)`;
    }
  }
}

