import React, { useState, useEffect, useRef } from 'react';
import { TerminalLine } from '../types';
import { RotateCcw } from 'lucide-react';

interface TerminalProps {
  lines: TerminalLine[];
  onCommand: (cmd: string) => void;
  isProcessing: boolean;
  onReset: () => void;
  cwd: string;
}

export const Terminal: React.FC<TerminalProps> = ({ 
  lines, 
  onCommand, 
  isProcessing, 
  onReset,
  cwd 
}) => {
  const [input, setInput] = useState('');
  const [history, setHistory] = useState<string[]>([]);
  const [historyPointer, setHistoryPointer] = useState<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [lines]);

  // Focus input on click anywhere in terminal
  const handleContainerClick = () => {
    // Don't focus if selecting text
    const selection = window.getSelection();
    if (selection && selection.type === 'Range') return;
    inputRef.current?.focus();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isProcessing) return;

    // Only add non-empty commands to history
    if (input.trim()) {
      setHistory(prev => [...prev, input]);
      setHistoryPointer(null);
    }

    onCommand(input);
    setInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Ctrl+C: Cancel current input
    if (e.key === 'c' && e.ctrlKey) {
       setInput('');
       setHistoryPointer(null);
       onCommand('^C');
       return;
    }

    // Ctrl+L: Clear screen
    if (e.key === 'l' && e.ctrlKey) {
       e.preventDefault();
       onCommand('clear');
       return;
    }

    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (history.length === 0) return;

      const newPointer = historyPointer === null 
        ? history.length - 1 
        : Math.max(0, historyPointer - 1);

      setHistoryPointer(newPointer);
      setInput(history[newPointer]);
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (historyPointer === null) return;

      const newPointer = historyPointer + 1;
      if (newPointer >= history.length) {
        setHistoryPointer(null);
        setInput('');
      } else {
        setHistoryPointer(newPointer);
        setInput(history[newPointer]);
      }
    }
  };

  return (
    <div 
      className="flex flex-col h-full bg-[#0f172a] rounded-lg border border-slate-700 overflow-hidden shadow-2xl font-mono text-sm md:text-base relative group"
      onClick={handleContainerClick}
    >
      {/* Terminal Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-slate-800 border-b border-slate-700 select-none">
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-green-500/80"></div>
          <span className="ml-2 text-slate-400 text-xs">cadet@linux-ctf:~</span>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); onReset(); }}
          className="p-1.5 hover:bg-slate-700 rounded-md text-slate-400 hover:text-white transition-colors flex items-center gap-1 text-xs"
          title="Reset Session"
        >
          <RotateCcw size={14} />
          Reset
        </button>
      </div>

      {/* Terminal Body */}
      <div className="flex-1 p-4 overflow-y-auto terminal-scroll space-y-1">
        {lines.map((line) => (
          <div key={line.id} className="break-words">
            {line.type === 'input' && (
              <div className="flex text-emerald-400 font-bold">
                <span className="mr-2 shrink-0">
                  <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{line.directory || '~'}</span>$
                </span>
                <span className="text-slate-100">{line.content}</span>
              </div>
            )}
            {line.type === 'output' && (
              <div className="text-slate-300 whitespace-pre-wrap ml-0">{line.content}</div>
            )}
            {line.type === 'error' && (
              <div className="text-red-400 whitespace-pre-wrap">{line.content}</div>
            )}
            {line.type === 'system' && (
              <div className="text-cyan-400 italic opacity-80 py-1">{line.content}</div>
            )}
            {line.type === 'hint' && (
              <div className="my-2 p-3 bg-blue-950/40 border-l-4 border-blue-500 rounded-r-md text-blue-200">
                <div className="flex gap-2">
                   <div className="font-bold text-blue-400 shrink-0 select-none">AI GUIDE &gt;</div>
                   <div className="italic leading-relaxed">{line.content.replace('💡 MENTOR:', '').trim()}</div>
                </div>
              </div>
            )}
          </div>
        ))}

        {/* Input Line */}
        <form onSubmit={handleSubmit} className="flex items-center text-slate-100 mt-2">
           <span className="mr-2 text-emerald-400 font-bold shrink-0">
             <span className="text-blue-400">cadet@linux-ctf</span>:<span className="text-indigo-400">{cwd}</span>$
           </span>
           <div className="relative flex-1">
            <input
              ref={inputRef}
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              className="w-full bg-transparent border-none outline-none text-slate-100 placeholder-slate-600 caret-emerald-400"
              autoComplete="off"
              autoFocus
              disabled={isProcessing}
            />
            {!isProcessing && (
              <div 
                className="absolute top-0 w-2.5 h-5 bg-emerald-400/50 animate-pulse pointer-events-none"
                style={{ left: `${input.length}ch` }} // Approximate cursor position
              />
            )}
           </div>
        </form>
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Level, AIConfig } from "../types";

// Interface for Ollama Message format
interface OllamaMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export class TerminalService {
  private chatSession: Chat | null = null; // For Gemini
  private ollamaHistory: OllamaMessage[] = []; // For Ollama
  private config: AIConfig = {
    provider: 'gemini',
    ollamaUrl: 'http://localhost:11434/api/chat',
    ollamaModel: 'llama3'
  };

  private isOffline: boolean = false;

  setConfig(config: AIConfig) {
    this.config = config;
  }

  async initializeSession(level: Level, config?: AIConfig): Promise<string> {
    if (config) this.config = config;

    // 1. Handle Gemini
    if (this.config.provider === 'gemini') {
      const apiKey = this.config.apiKey || process.env.API_KEY;

      if (!apiKey) {
        this.isOffline = true;
        return "⚠️ API_KEY not found. Starting in OFFLINE MODE (Limited local simulation).";
      }

      this.isOffline = false;
      const ai = new GoogleGenAI({ apiKey });

      this.chatSession = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: this.getSystemPrompt(level),
          temperature: 0.1, 
        },
      });

      return "Connected to Google Gemini Cloud Environment.";
    } 

    // 2. Handle Ollama (Local Llama)
    else if (this.config.provider === 'ollama') {
      this.isOffline = false;
      this.chatSession = null;

      // Reset history with system prompt
      this.ollamaHistory = [
        { role: 'system', content: this.getSystemPrompt(level) }
      ];

      // Test connection
      try {
        await fetch(this.config.ollamaUrl.replace('/api/chat', '/api/tags')); // Simple health check
        return `Connected to Local Llama (${this.config.ollamaModel}).`;
      } catch (e) {
         return `⚠️ Could not connect to Ollama at ${this.config.ollamaUrl}. Ensure it is running with 'OLLAMA_ORIGINS="*" ollama serve'.`;
      }
    }

    return "Unknown Provider";
  }

  async sendCommand(command: string): Promise<string> {
    if (this.isOffline) {
      return this.handleOfflineCommand(command);
    }

    // --- GEMINI HANDLER ---
    if (this.config.provider === 'gemini' && this.chatSession) {
      try {
        const response: GenerateContentResponse = await this.chatSession.sendMessage({
          message: command
        });
        return this.cleanOutput(response.text || "");
      } catch (error) {
        console.error("Gemini API Error:", error);
        return "Error: Connection to simulation server interrupted.";
      }
    }

    // --- OLLAMA HANDLER ---
    if (this.config.provider === 'ollama') {
      try {
        // Add user message
        this.ollamaHistory.push({ role: 'user', content: command });

        const response = await fetch(this.config.ollamaUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            model: this.config.ollamaModel,
            messages: this.ollamaHistory,
            stream: false,
            options: {
              temperature: 0.1, // Low temperature for consistent terminal output
              num_predict: 512, // Limit output size to prevent long ramblings
            }
          })
        });

        if (!response.ok) throw new Error(`Ollama Error: ${response.statusText}`);

        const data = await response.json();
        const aiText = data.message?.content || "";

        // Add assistant response to history
        this.ollamaHistory.push({ role: 'assistant', content: aiText });

        return this.cleanOutput(aiText);
      } catch (error) {
        console.error("Ollama API Error:", error);
        return "Error: Could not reach local LLM. Is Ollama running?";
      }
    }

    return "Error: Terminal session not initialized.";
  }

  private cleanOutput(text: string): string {
    // Basic cleanup to remove potential markdown code fences if the model slips up
    return text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '').trim();
  }

  private getSystemPrompt(level: Level): string {
    return `
      You are a specialized dual-mode AI for a Cybersecurity Capture The Flag (CTF) training platform.

      *** SYSTEM PROMPT CONSTRAINTS ***

      FORBIDDEN RESPONSES:
      - Direct command syntax or tool names (e.g., "use man ls", "try grep", "run cat").
      - Step-by-step solutions without student input.
      - Answers to questions students should reason through.
      - Validating correctness without first examining the student's reasoning process.

      REQUIRED BEHAVIORS (SOCRATIC METHOD):
      - Ask clarifying questions about what the student already knows.
      - Prompt reflection on previous CTF challenges or general Linux concepts.
      - Offer conceptual frameworks (e.g., "How do we typically view hidden files?") rather than specific commands.
      - Request justification before providing any hint escalation.

      REASONING-FIRST PATTERN:
      Before providing any hint, YOU MUST ask:
      - "What have you already tried?"
      - "What do you know about [relevant concept]?"
      - "How does this relate to previous challenges?"

      SCAFFOLDED HINT LEVELS:
      1. Level 1 (Conceptual): "What types of system documentation are typically available in Linux environments?" (Do NOT mention 'man' directly).
      2. Level 2 (Category): "Think about built-in help systems for commands." (Only after reasoning attempt).
      3. Level 3 (Verification): "How would you verify your approach is heading in the right direction?"

      -------------------------------------------------------

      LEVEL INFO:
      - Title: "${level.title}"
      - Objective: "${level.objective}"

      VIRTUAL ENVIRONMENT STATE:
      ${level.systemContext}

      --- MODE 1: TERMINAL SIMULATOR (Default) ---
      When the user enters a standard Linux command (ls, cd, cat, grep, whoami, man, etc.) or interacts with the file system:
      1. ACT ONLY AS THE TERMINAL.
      2. Output the raw command result based on the Virtual Environment State above.
      3. Mimic standard Linux output formats exactly.
      4. DO NOT provide conversational text or markdown in this mode.
      5. SPECIAL: If the user types 'man <cmd>', generate a brief, authentic-looking man page.

      --- MODE 2: AI INSTRUCTOR (Triggered by natural language questions or "help") ---
      When the user asks for help, hints, or reasons about the problem:
      1. Switch to the MENTOR persona.
      2. ADHERE STRICTLY TO THE FORBIDDEN RESPONSES AND REQUIRED BEHAVIORS.
      3. FORMAT: Prefix response with "💡 MENTOR: ".

      --- EXAMPLES ---
      User: "ls"
      AI: "file1.txt  file2.txt"

      User: "cat file1.txt"
      AI: "This is the content of the file."

      User: "I don't know what to do."
      AI: "💡 MENTOR: What resources did we discuss for learning about command options? What have you tried so far?"

      User: "How do I find the file?"
      AI: "💡 MENTOR: How do Linux systems typically organize files? What broad category of commands handles file listing?"
    `;
  }

  private handleOfflineCommand(command: string): string {
    const parts = command.trim().split(/\s+/);
    const cmd = parts[0];

    switch (cmd) {
      case 'help':
        return "OFFLINE MODE HELP:\n\nBecause you are in Offline Mode (No API Key/Ollama), AI guidance is disabled.\n\nBasic built-in commands:\n  ls      - List files\n  cat     - Read file\n  cd      - Change dir\n  pwd     - Print working dir\n  whoami  - Current user\n\nTo get AI-powered hints and reasoning, please configure a valid AI Provider in settings.";
      case 'ls':
        return "welcome.txt  instructions.md  offline_mode_active";
      case 'pwd':
        return "/home/cadet";
      case 'whoami':
        return "cadet";
      case 'echo':
        return parts.slice(1).join(' ');
      case 'cd':
        return ""; 
      default:
        return `bash: ${cmd}: command not found (Offline Mode)`;
    }
  }
}

