import React, { useState, useEffect } from 'react';
import { X, Save, Server, Cloud, Cpu, Box, Globe, ShieldCheck, Lock, CheckCircle, Users, RefreshCw, Key } from 'lucide-react';
import { AIConfig, AIProvider, User } from '../types';
import { authService } from '../services/authService';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: AIConfig;
  onSave: (config: AIConfig) => void;
}

type TabType = AIProvider | 'security' | 'users';

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  config,
  onSave
}) => {
  const [localConfig, setLocalConfig] = useState<AIConfig>(config);
  const [activeTab, setActiveTab] = useState<TabType>(config.provider);

  // Password Change State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  // User Management State
  const [studentList, setStudentList] = useState<User[]>([]);
  const [selectedStudent, setSelectedStudent] = useState<string | null>(null);
  const [resetPassValue, setResetPassValue] = useState('');
  const [resetMsg, setResetMsg] = useState('');

  useEffect(() => {
    setLocalConfig(config);
    setActiveTab(config.provider);
    setPasswordMsg(null);
    setNewPassword('');
    setConfirmPassword('');

    // Refresh student list when opening
    if (isOpen) {
       setStudentList(authService.getAllStudents());
       setSelectedStudent(null);
       setResetPassValue('');
       setResetMsg('');
    }
  }, [config, isOpen]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...localConfig, provider: (activeTab === 'security' || activeTab === 'users') ? config.provider : activeTab });
    onClose();
  };

  const handleChangePassword = () => {
     if (newPassword !== confirmPassword) {
       setPasswordMsg({ type: 'error', text: 'Passwords do not match' });
       return;
     }
     try {
       authService.changeAdminPassword(newPassword);
       setPasswordMsg({ type: 'success', text: 'Password updated successfully' });
       setNewPassword('');
       setConfirmPassword('');
     } catch (e: any) {
       setPasswordMsg({ type: 'error', text: e.message });
     }
  };

  const handleResetStudentPass = () => {
    if (!selectedStudent || !resetPassValue) return;
    try {
      authService.resetStudentPassword(selectedStudent, resetPassValue);
      setResetMsg(`Success: Password for ${selectedStudent} reset.`);
      setResetPassValue('');
      setTimeout(() => setResetMsg(''), 3000);
    } catch (e: any) {
      setResetMsg(`Error: ${e.message}`);
    }
  };

  if (!isOpen) return null;

  const renderTabButton = (id: TabType, label: string, icon: React.ReactNode, colorClass: string) => (
    <button
      type="button"
