import React, { useState } from 'react';
import { User } from '../types';
import { authService } from '../services/authService';
import { Shield, User as UserIcon, Lock, UserPlus, LogIn } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [role, setRole] = useState<'student' | 'admin'>('student');
  const [isRegistering, setIsRegistering] = useState(true); // Default to register for new users

  const [username, setUsername] = useState('');
  const [studentPassword, setStudentPassword] = useState('');

  const [adminUsername, setAdminUsername] = useState('');
  const [adminPassword, setAdminPassword] = useState('');

  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    try {
      if (role === 'student') {
        if (!username.trim()) {
          setError('Please enter a username');
          return;
        }
        if (!studentPassword.trim()) {
          setError('Please enter a password');
          return;
        }

        const user = isRegistering 
          ? authService.registerStudent(username, studentPassword) 
          : authService.loginStudent(username, studentPassword);

        onLogin(user);
      } else {
        if (!adminUsername.trim() || !adminPassword.trim()) {
           setError('Please enter both username and password');
           return;
        }

        const user = authService.loginAsAdmin(adminUsername, adminPassword);
        if (user) {
          onLogin(user);
        } else {
          setError('Invalid admin credentials');
        }
      }
    } catch (err: any) {
      setError(err.message || 'Authentication failed');
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-950 p-4 font-sans">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-xl shadow-2xl p-8">

        {/* Logo Section */}
        <div className="flex flex-col items-center mb-8">
          <div className="p-3 bg-red-600/10 rounded-full mb-4 ring-1 ring-red-500/50">
            <Shield className="text-red-500 w-10 h-10" />
          </div>
          <h1 className="text-2xl font-bold text-white text-center tracking-tight">Linux Gym</h1>
          <p className="text-slate-400 text-sm mt-2 text-center">
            Cyber Security Training Environment
          </p>
        </div>

        {/* Role Toggles */}
        <div className="flex bg-slate-950 p-1 rounded-lg mb-6 border border-slate-800">
          <button
            onClick={() => { setRole('student'); setError(''); }}
            className={`flex-1 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
              role === 'student' ? 'bg-slate-800 text-white shadow ring-1 ring-slate-700' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            Student Access
          </button>
          <button
            onClick={() => { setRole('admin'); setError(''); }}
            className={`flex-1 py-2 text-sm font-medium rounded-md transition-all duration-200 ${
              role === 'admin' ? 'bg-slate-800 text-white shadow ring-1 ring-slate-700' : 'text-slate-500 hover:text-slate-300'
            }`}
          >
            Admin Portal
          </button>
        </div>

        {/* Student Specific Sub-Toggles */}
        {role === 'student' && (
           <div className="flex justify-center space-x-6 mb-6 text-sm border-b border-slate-800 pb-2">
              <button 
                onClick={() => { setIsRegistering(true); setError(''); }}
                className={`pb-2 transition-colors ${isRegistering ? 'text-red-400 border-b-2 border-red-500 font-semibold' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Register Account
              </button>
              <button 
                onClick={() => { setIsRegistering(false); setError(''); }}
                className={`pb-2 transition-colors ${!isRegistering ? 'text-red-400 border-b-2 border-red-500 font-semibold' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Existing User
              </button>
           </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {role === 'student' ? (
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase mb-1.5 tracking-wider">
                   {isRegistering ? 'Create Username' : 'Enter Username'}
                </label>
                <div className="relative group">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    {isRegistering ? <UserPlus className="text-slate-500 w-4 h-4" /> : <LogIn className="text-slate-500 w-4 h-4" />}
                  </div>
                  <input
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-700 rounded-lg py-3 pl-10 pr-4 text-white placeholder-slate-600 focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-colors"
                    placeholder={isRegistering ? "e.g. user_01" : "Your registered username"}
                    autoFocus
                  />
                </div>
              </div>

              <div>
                  <label className="block text-xs font-semibold text-slate-400 uppercase mb-1.5 tracking-wider">
                    {isRegistering ? 'Create Password' : 'Password'}
                  </label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-3 text-slate-500 w-4 h-4" />
                    <input
                      type="password"
                      value={studentPassword}
                      onChange={(e) => setStudentPassword(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg py-3 pl-10 pr-4 text-white placeholder-slate-600 focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-colors"
                      placeholder="••••••••"
                    />
                  </div>
               </div>

              {isRegistering && (
                <p className="text-[10px] text-slate-500">
                  * This will create a temporary tracking ID for your research session.
                </p>
              )}
            </div>
          ) : (
            <div className="space-y-4">
               <div>
                  <label className="block text-xs font-semibold text-slate-400 uppercase mb-1.5 tracking-wider">Username</label>
                  <div className="relative">
                    <UserIcon className="absolute left-3 top-3 text-slate-500 w-4 h-4" />
                    <input
                      type="text"
                      value={adminUsername}
                      onChange={(e) => setAdminUsername(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg py-3 pl-10 pr-4 text-white placeholder-slate-600 focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-colors"
                      placeholder="admin"
                    />
                  </div>
               </div>
               <div>
                  <label className="block text-xs font-semibold text-slate-400 uppercase mb-1.5 tracking-wider">Password</label>
                  <div className="relative">
                    <Lock className="absolute left-3 top-3 text-slate-500 w-4 h-4" />
                    <input
                      type="password"
                      value={adminPassword}
                      onChange={(e) => setAdminPassword(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg py-3 pl-10 pr-4 text-white placeholder-slate-600 focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-colors"
                      placeholder="••••••••"
                    />
                  </div>
                  <p className="text-[10px] text-slate-600 mt-2 text-center">Default: <code className="bg-slate-800 px-1 py-0.5 rounded text-slate-400">admin</code></p>
               </div>
            </div>
          )}

          {error && (
            <div className="p-3 bg-red-900/20 border border-red-900/50 rounded-lg flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
              <div className="w-1.5 h-1.5 rounded-full bg-red-500 shrink-0" />
              <p className="text-red-300 text-xs font-medium">{error}</p>
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-gradient-to-r from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 text-white font-bold py-3 rounded-lg transition-all shadow-lg shadow-red-900/30 active:scale-[0.98] border border-red-500/50"
          >
            {role === 'student' 
              ? (isRegistering ? 'Create Account & Start' : 'Resume Session') 
              : 'Authenticate Admin'}
          </button>
        </form>
      </div>

      <p className="mt-8 text-slate-600 text-xs text-center max-w-xs leading-relaxed">
        Restricted Access System.<br/>Authorized Personnel Only.
      </p>
    </div>
  );
};

