                />
                <p className="text-[10px] text-slate-500">Uses 'gemini-3-flash-preview' by default.</p>
              </div>
            )}

            {activeTab === 'ollama' && (
              <div className="space-y-4">
                 <label className="text-xs font-semibold text-orange-400 uppercase tracking-wider">Local Ollama Config</label>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] text-slate-400 mb-1">Endpoint URL</label>
                      <input
                        type="text"
                        value={localConfig.ollamaUrl}
                        onChange={(e) => setLocalConfig({ ...localConfig, ollamaUrl: e.target.value })}
                        className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-sm focus:border-orange-500 outline-none"
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] text-slate-400 mb-1">Model Name</label>
                      <input
                        type="text"
                        value={localConfig.ollamaModel}
                        placeholder="llama3"
                        onChange={(e) => setLocalConfig({ ...localConfig, ollamaModel: e.target.value })}
