import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Level, AIConfig, ResearchLog, CEWMetric, User } from "../types";

// Interface for Message formats
interface BaseMessage {
  role: string;
  content: string;
}

export class TerminalService {
  private chatSession: Chat | null = null; // For Gemini
  private messageHistory: BaseMessage[] = []; // For Ollama/OpenAI/Anthropic
  private researchLogs: ResearchLog[] = []; // Store session data

  private config: AIConfig = {
    provider: 'gemini',
    ollamaUrl: 'http://localhost:11434/api/chat',
    ollamaModel: 'llama3',
    openaiModel: 'gpt-4o',
    anthropicModel: 'claude-3-5-sonnet-20240620'
  };

  private isOffline: boolean = false;
  private currentLevel: Level | null = null;
  private currentUser: User | null = null;

  setConfig(config: AIConfig) {
    this.config = config;
  }

  async initializeSession(level: Level, user: User, config?: AIConfig): Promise<string> {
    if (config) this.config = config;
    this.currentLevel = level;
    this.currentUser = user;

    // Reset history for non-Gemini providers
    this.messageHistory = [
      { role: 'system', content: this.getSystemPrompt(level) }
    ];

    try {
      switch (this.config.provider) {
        case 'gemini':
          return this.initGemini(level);
        case 'ollama':
          return await this.initOllama();
        case 'openai':
          return "Connected to OpenAI (GPT).";
        case 'anthropic':
          return "Connected to Anthropic (Claude).";
        case 'custom':
          return `Connected to Custom Endpoint (${this.config.openaiUrl}).`;
        default:
          return "Unknown Provider";
      }
    } catch (e) {
      this.isOffline = true;
      return `⚠️ Connection Failed: ${e}. Starting in OFFLINE MODE.`;
    }
  }

  // --- INITIALIZATION HELPERS ---

  private async initGemini(level: Level): Promise<string> {
    const apiKey = this.config.apiKey || process.env.API_KEY;
    if (!apiKey) {
      this.isOffline = true;
      return "⚠️ API_KEY not found. Starting in OFFLINE MODE.";
    }
    this.isOffline = false;
    const ai = new GoogleGenAI({ apiKey });
    this.chatSession = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: this.getSystemPrompt(level),
        temperature: 0.1, 
      },
    });
    return "Connected to Google Gemini Cloud Environment.";
  }

  private async initOllama(): Promise<string> {
    this.isOffline = false;
    this.chatSession = null;
    try {
      await fetch(this.config.ollamaUrl.replace('/api/chat', '/api/tags'));
      return `Connected to Local Llama (${this.config.ollamaModel}).`;
    } catch (e) {
      throw new Error(`Could not connect to Ollama at ${this.config.ollamaUrl}`);
    }
  }

  // --- COMMAND HANDLING ---

  async sendCommand(command: string): Promise<string> {
    if (this.isOffline) {
      return this.handleOfflineCommand(command);
    }

    try {
      let output = "";

      // 1. EXECUTE THE TUTOR (The response visible to user)
      switch (this.config.provider) {
        case 'gemini':
          output = await this.handleGemini(command);
          break;
        case 'ollama':
          output = await this.handleOllama(command);
          break;
        case 'openai':
        case 'custom':
          output = await this.handleOpenAICompatible(command);
          break;
        case 'anthropic':
          output = await this.handleAnthropic(command);
          break;
        default:
          output = "Error: Unknown provider configured.";
      }

      // 2. EXECUTE THE SHADOW EVALUATOR (The background researcher)
      // Only log if we have a user
      if (this.currentUser) {
          this.runShadowEvaluator(command, output).catch(e => console.error("Shadow Eval Failed:", e));
      }

      return output;

    } catch (error) {
      console.error(`${this.config.provider} Error:`, error);
      return `Error: Communication with ${this.config.provider} failed. Check console for details.`;
    }
  }

  // --- SHADOW EVALUATOR (RESEARCH LAYER) ---

  private async runShadowEvaluator(command: string, aiResponse: string) {
    if (!this.currentLevel || !this.currentUser) return;

    // EXACT PROMPT FROM SPECIFICATION
    const evaluatorPrompt = `
      Analyze the last student message in the context of this CTF level.
      Student Message: "${command}"
      Current Context: ${this.currentLevel.systemContext}

      Output a JSON object with these metrics for my research:
      {
        "claim_present": boolean, // Did they state a goal or hypothesis?
        "evidence_present": boolean, // Did they refer to actual terminal output/files?
        "warrant_present": boolean, // Did they explain WHY the evidence leads to the claim?
        "reasoning_level": 1-5, // 1=Guessing, 5=Scientifically Sound
        "misconception_detected": string or null // Describe any logic error
      }
    `;

    try {
        let rawJson = "{}";

        if (this.config.provider === 'gemini') {
            const apiKey = this.config.apiKey || process.env.API_KEY;
            const ai = new GoogleGenAI({ apiKey });

            const result = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: evaluatorPrompt,
                config: { responseMimeType: "application/json" }
            });
            rawJson = result.text || "{}";
        } 
        else if (this.config.provider === 'openai' || this.config.provider === 'custom') {
           const url = this.config.provider === 'openai' ? 'https://api.openai.com/v1/chat/completions' : this.config.openaiUrl!;
           const key = this.config.provider === 'openai' ? this.config.openaiKey : 'lm-studio';

           const res = await fetch(url, {
             method: 'POST',
             headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
             body: JSON.stringify({
               model: this.config.openaiModel || 'gpt-4o',
               messages: [{ role: 'user', content: evaluatorPrompt }],
               response_format: { type: "json_object" }
             })
           });
           const data = await res.json();
           rawJson = data.choices[0].message.content;
        }

        const metrics: CEWMetric = JSON.parse(rawJson);

        this.researchLogs.push({
            timestamp: new Date().toISOString(),
            userId: this.currentUser.id,
            username: this.currentUser.username,
            levelId: this.currentLevel.id,
            type: 'command',
            input: command,
            output: aiResponse,
            metrics
        });

        // Console log for admin debugging
        console.log(`[Shadow Eval] User: ${this.currentUser.username} | Score: ${metrics.reasoning_level}/5`);

    } catch (e) {
        console.warn("Evaluator error:", e);
    }
  }

  // --- LOGGING FLAG ATTEMPTS ---
  public logFlagAttempt(flagAttempt: string, isCorrect: boolean) {
     if (!this.currentLevel || !this.currentUser) return;

     this.researchLogs.push({
        timestamp: new Date().toISOString(),
        userId: this.currentUser.id,
        username: this.currentUser.username,
        levelId: this.currentLevel.id,
        type: 'flag_attempt',
        input: flagAttempt,
        output: isCorrect ? 'SUCCESS' : 'FAILED',
        isCorrect
     });
  }

  public getResearchLogs(): ResearchLog[] {
      return this.researchLogs;
  }

  public downloadLogs() {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(this.researchLogs, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `ctf_research_logs_${new Date().toISOString()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  }

  // --- AI HANDLERS ---

  private async handleGemini(command: string): Promise<string> {
    if (!this.chatSession) throw new Error("Gemini session not found");
    const response: GenerateContentResponse = await this.chatSession.sendMessage({
      message: command
    });
    return this.cleanOutput(response.text || "");
  }

  private async handleOllama(command: string): Promise<string> {
    this.messageHistory.push({ role: 'user', content: command });

    const response = await fetch(this.config.ollamaUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: this.config.ollamaModel,
        messages: this.messageHistory,
        stream: false,
        options: { temperature: 0.1, num_predict: 512 }
      })
    });

    if (!response.ok) throw new Error(`Ollama API Error: ${response.status}`);
    const data = await response.json();
    const aiText = data.message?.content || "";
    this.messageHistory.push({ role: 'assistant', content: aiText });
    return this.cleanOutput(aiText);
  }

  private async handleOpenAICompatible(command: string): Promise<string> {
    const url = this.config.provider === 'openai' 
      ? 'https://api.openai.com/v1/chat/completions' 
      : this.config.openaiUrl || 'http://localhost:1234/v1/chat/completions'; 

    const apiKey = this.config.provider === 'openai' 
      ? this.config.openaiKey 
      : this.config.openaiKey || 'lm-studio';

    this.messageHistory.push({ role: 'user', content: command });

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model: this.config.openaiModel || (this.config.provider === 'openai' ? 'gpt-4o' : 'local-model'),
        messages: this.messageHistory,
        temperature: 0.1,
        max_tokens: 512
      })
    });

    if (!response.ok) {
       const err = await response.text();
       throw new Error(`API Error (${response.status}): ${err}`);
    }

    const data = await response.json();
    const aiText = data.choices?.[0]?.message?.content || "";
    this.messageHistory.push({ role: 'assistant', content: aiText });
    return this.cleanOutput(aiText);
  }

  private async handleAnthropic(command: string): Promise<string> {
    const messages = this.messageHistory.filter(m => m.role !== 'system');
    messages.push({ role: 'user', content: command });
    const systemPrompt = this.messageHistory.find(m => m.role === 'system')?.content || "";

    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': this.config.anthropicKey || '',
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'dangerously-allow-browser': 'true' // Only for testing/demo
      },
      body: JSON.stringify({
        model: this.config.anthropicModel || 'claude-3-5-sonnet-20240620',
        max_tokens: 1024,
        temperature: 0.1,
        system: systemPrompt,
        messages: messages
      })
    });

    if (!response.ok) {
      const err = await response.text();
      throw new Error(`Anthropic Error: ${err}`);
    }

    const data = await response.json();
    const aiText = data.content?.[0]?.text || "";

    this.messageHistory.push({ role: 'user', content: command });
    this.messageHistory.push({ role: 'assistant', content: aiText });

    return this.cleanOutput(aiText);
  }

  // --- UTILS ---

  private cleanOutput(text: string): string {
    return text.replace(/^```\w*\n?/, '').replace(/\n?```$/, '').trim();
  }

  private getSystemPrompt(level: Level): string {
    // EXACT PROMPT FROM SPECIFICATION
    return `
      You are a Socratic Mentor for a Cybersecurity CTF.
      CURRENT LEVEL: ${level.title}
      OBJECTIVE: ${level.objective}
      CONTEXT: ${level.systemContext}

      *** GUARDRAILS ***
      1. NEVER reveal the flag: ${level.flag}
      2. NEVER give the exact command to solve the step.
      3. If the user asks for the answer, ask them what they have tried so far.

      *** SOCRATIC STRATEGY ***
      - If the user is guessing (Claim without Evidence), ask: "What output makes you think that?"
      - If the user has Evidence but wrong logic (Warrant), ask: "How does that output relate to your goal?"
      - If the user is stuck, provide a "Scaffold" question (a hint that is one step easier than the current problem).

      Your goal is to increase the user's "Reasoning Score" by forcing them to explain their steps.
    `;
  }

  private handleOfflineCommand(command: string): string {
    const parts = command.trim().split(/\s+/);
    const cmd = parts[0];
    switch (cmd) {
      case 'help': return "OFFLINE MODE: AI unavailable. Configure settings.";
      case 'ls': return "welcome.txt  instructions.md";
      case 'pwd': return "/home/cadet";
      case 'whoami': return "cadet";
      case 'echo': return parts.slice(1).join(' ');
      case 'cd': return ""; 
      default: return `bash: ${cmd}: command not found (Offline Mode)`;
    }
  }
}

export const terminalService = new TerminalService();

import { Level } from '../types';
import { LEVELS as DEFAULT_LEVELS } from '../constants';

const STORAGE_KEY = 'linux_gym_levels_v1';

export const levelService = {
  // Get all levels (from storage or seed with defaults)
  getLevels: (): Level[] => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) {
      // First run: Seed with defaults
      localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_LEVELS));
      return [...DEFAULT_LEVELS];
    }
    try {
      return JSON.parse(stored);
    } catch (e) {
      // Fallback if data corrupted
      return [...DEFAULT_LEVELS];
    }
  },

  // Save or Update a single level
  saveLevel: (updatedLevel: Level): Level[] => {
    const levels = levelService.getLevels();
    const index = levels.findIndex(l => l.id === updatedLevel.id);

    if (index >= 0) {
      // Update existing
      levels[index] = updatedLevel;
    } else {
      // Create new: Auto-increment ID if needed
      const maxId = levels.length > 0 ? Math.max(...levels.map(l => l.id)) : 0;
      updatedLevel.id = maxId + 1;
      levels.push(updatedLevel);
    }

    localStorage.setItem(STORAGE_KEY, JSON.stringify(levels));
    return levels;
  },

  // Import entire list (Overwrite)
  importLevels: (newLevels: Level[]): Level[] => {
     localStorage.setItem(STORAGE_KEY, JSON.stringify(newLevels));
     return newLevels;
  },

  // Delete a level
  deleteLevel: (id: number): Level[] => {
      let levels = levelService.getLevels();
      levels = levels.filter(l => l.id !== id);
      // Re-sort to ensure order? Or keep gaps? Let's keep gaps for ID stability.
      localStorage.setItem(STORAGE_KEY, JSON.stringify(levels));
      return levels;
  },

  // Reset to original hardcoded constants
  resetDefaults: (): Level[] => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_LEVELS));
    return [...DEFAULT_LEVELS];
  }
};

