import React, { useState, useEffect, useRef } from 'react';
import { X, Save, Server, Cloud, Cpu, Box, Globe, ShieldCheck, Lock, CheckCircle, Users, RefreshCw, Key, Edit, Trash, Plus, FileText, HelpCircle, Flag, Download, Upload } from 'lucide-react';
import { AIConfig, AIProvider, User, Level, Difficulty } from '../types';
import { authService } from '../services/authService';
import { levelService } from '../services/levelService';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: AIConfig;
  onSave: (config: AIConfig) => void;
  onLevelsChange?: () => void; // New callback for level updates
}

type TabType = AIProvider | 'security' | 'users' | 'levels';

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  config,
  onSave,
  onLevelsChange
}) => {
  const [localConfig, setLocalConfig] = useState<AIConfig>(config);
  const [activeTab, setActiveTab] = useState<TabType>(config.provider);

  // Password Change State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  // User Management State
  const [studentList, setStudentList] = useState<User[]>([]);
  const [selectedStudent, setSelectedStudent] = useState<string | null>(null);
  const [resetPassValue, setResetPassValue] = useState('');
  const [resetMsg, setResetMsg] = useState('');

  // Level Editor State
  const [levels, setLevels] = useState<Level[]>([]);
  const [editingLevel, setEditingLevel] = useState<Level | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setLocalConfig(config);
    setActiveTab(config.provider);
    setPasswordMsg(null);
    setNewPassword('');
    setConfirmPassword('');

    // Refresh lists when opening
    if (isOpen) {
       setStudentList(authService.getAllStudents());
       setLevels(levelService.getLevels());
       setSelectedStudent(null);
       setResetPassValue('');
       setResetMsg('');
       setIsEditing(false);
       setEditingLevel(null);
    }
  }, [config, isOpen]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...localConfig, provider: (activeTab === 'security' || activeTab === 'users' || activeTab === 'levels') ? config.provider : activeTab });
    onClose();
  };

  const handleChangePassword = () => {
     if (newPassword !== confirmPassword) {
       setPasswordMsg({ type: 'error', text: 'Passwords do not match' });
       return;
     }
     try {
       authService.changeAdminPassword(newPassword);
       setPasswordMsg({ type: 'success', text: 'Password updated successfully' });
       setNewPassword('');
       setConfirmPassword('');
